const articles=[{id:'brincar',title:'A importância do brincar no desenvolvimento infantil',desc:'Entenda como a brincadeira participa da construção de habilidades, vínculos e descobertas.',img:'toy-03.webp',body:'Brincar é uma forma essencial de a criança conhecer o mundo. Ao experimentar, imaginar, repetir e compartilhar, ela constrói hipóteses, desenvolve habilidades motoras e amplia a linguagem. Mais importante do que oferecer muitos brinquedos é criar tempo, presença e liberdade para explorar.'},{id:'idade',title:'Como escolher brinquedos por faixa etária',desc:'Um guia para observar interesses, segurança e momento de desenvolvimento.',img:'toy-07.webp',body:'A faixa etária é um ponto de partida, não uma regra rígida. Observe os interesses, a experiência e o ritmo da criança. Confira sempre a indicação do fabricante, a presença de peças pequenas, materiais, acabamento e orientações de uso. A brincadeira deve ser prazerosa, possível e segura.'},{id:'consciente',title:'Consumo consciente: menos excesso, mais significado',desc:'Ideias para valorizar a qualidade das experiências e o reuso.',img:'toy-04.webp',body:'Consumo consciente também faz parte da infância. Alternar brinquedos, compartilhar, reparar e doar itens em boas condições são atitudes que ajudam a reduzir o excesso. O objetivo não é limitar a brincadeira, mas abrir espaço para experiências mais significativas.'}];
const plansById=id=>plans.find(p=>p.id===id); const productById=id=>products.find(p=>p.id===id); const money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
let cart=JSON.parse(localStorage.getItem('bambin-cart')||'[]'), favorites=JSON.parse(localStorage.getItem('bambin-favorites')||'[]'), activeFilter='all', searchTerm='', checkoutData={}, checkoutStep=1;
const app=document.getElementById('app'); const toastEl=document.getElementById('toast');
function persist(){localStorage.setItem('bambin-cart',JSON.stringify(cart));localStorage.setItem('bambin-favorites',JSON.stringify(favorites));updateCounts();}
function updateCounts(){document.getElementById('cartCount').textContent=cart.reduce((n,i)=>n+i.qty,0);document.getElementById('favoriteCount').textContent=favorites.length;}
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2600)}
function go(hash){location.hash=hash}
function productCard(p){return `<article class="product-card"><div class="product-photo"><img src="assets/${p.image}" alt="Brinquedo ${p.name}" loading="lazy"><button class="favorite-toggle ${favorites.includes(p.id)?'active':''}" data-fav="${p.id}" aria-label="${favorites.includes(p.id)?'Remover dos':'Adicionar aos'} favoritos">${favorites.includes(p.id)?'♥':'♡'}</button></div><div class="product-info"><span class="card-age">${p.age}</span><h3>${p.name}</h3><p>${p.short}</p><div class="product-meta"><span class="price">${money(p.price)}</span><button class="text-link" data-product="${p.id}">Ver detalhes</button></div><div class="product-actions"><button class="btn btn-primary" data-add="${p.id}">Adicionar à sacola</button><button class="btn btn-outline" data-product="${p.id}">Detalhes</button></div></div></article>`}
function home(){const featured=products.slice(0,4);return `<section class="hero"><div class="hero-content"><div class="hero-copy"><span class="eyebrow">Brincar com propósito</span><h1>Brincar faz bem.<br>Escolher consciente<br>faz melhor ainda.</h1><p>Brinquedos que estimulam a imaginação, acompanham o desenvolvimento e transformam cada fase em uma nova descoberta.</p><div class="hero-actions"><a class="btn btn-primary" href="#brinquedos">Conheça nossos brinquedos ↗</a><a class="btn btn-brown" href="#clube">Descubra o clube de assinatura ↗</a></div></div></div></section><div class="trust-strip"><div class="trust-inner"><div class="trust-item"><span>✿</span><span>Brinquedos educativos<br>e de qualidade</span></div><div class="trust-item"><span>♡</span><span>Desenvolvimento<br>em cada fase</span></div><div class="trust-item"><span>♻</span><span>Consumo consciente<br>e sustentável</span></div><div class="trust-item"><span>◇</span><span>Clube de assinatura<br>com curadoria por idade</span></div><div class="trust-item"><span>♧</span><span>Incentivo à doação<br>e à reutilização</span></div></div></div><section class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Brinquedos por faixa etária</span><h2>Encontre o brinquedo ideal para cada fase.</h2><p>Seleções pensadas para acompanhar o desenvolvimento das crianças, do primeiro ao décimo ano de vida.</p></div><div class="age-grid">${ages.map(a=>`<article class="age-card"><img src="assets/${a.img}" alt="Criança explorando brinquedos educativos" loading="lazy"><div class="age-card-body"><span class="card-age">${a.age}</span><h3>${a.title}</h3><p>${a.desc}</p><button class="btn btn-primary btn-small" data-filter="${a.key}">Ver brinquedos →</button></div></article>`).join('')}</div></div></section><section class="section-tight"><div class="container"><div class="filters"><div><span class="eyebrow">Escolhas da Bambin</span><h2 style="font:600 32px var(--serif);color:var(--brown);margin:4px 0">Brinquedos em destaque</h2></div><a class="text-link" href="#brinquedos">Ver catálogo completo →</a></div><div class="product-grid">${featured.map(productCard).join('')}</div></div></section><section class="section"><div class="container"><div class="feature-band"><div class="feature-copy"><span class="eyebrow">Clube de assinatura Bambin</span><h2>Uma nova descoberta a cada ciclo.</h2><p>Uma curadoria pensada para a fase da criança, com experiências que acompanham o crescimento e dão novos sentidos ao brincar.</p><a class="btn btn-brown" href="#clube">Conheça os planos →</a></div><div class="feature-image" role="img" aria-label="Criança brincando com brinquedos educativos"></div></div></div></section><section class="section-tight"><div class="container"><div class="section-heading"><span class="eyebrow">Brincar faz crescer</span><h2>Muito mais que brinquedos: experiências que desenvolvem.</h2><p>Brincadeiras podem criar oportunidades para experimentar habilidades importantes, sempre com afeto e respeito ao ritmo de cada criança.</p></div><div class="benefit-grid">${benefitCards()}</div></div></section><section class="section"><div class="container"><div class="two-col"><img src="assets/sustainability-play.webp" alt="Ambiente de brincadeira com brinquedos de madeira" loading="lazy"><div class="copy-block"><span class="eyebrow">Nosso compromisso</span><h2>Bambin e o futuro: brincar também é cuidar.</h2><p>Acreditamos em escolhas mais conscientes: valorizar a durabilidade, compartilhar brinquedos em boas condições e reduzir o excesso sem abrir mão de experiências cheias de significado.</p><ul class="check-list"><li>Consumo consciente e escolhas responsáveis</li><li>Reutilização e compartilhamento</li><li>Incentivo à doação de brinquedos</li></ul><a class="text-link" href="#sustentabilidade">Conheça nosso compromisso →</a></div></div></div></section><section class="section-tight"><div class="container"><div class="feature-band"><div class="feature-copy"><span class="eyebrow">Iniciativa social</span><h2>Compartilhe histórias, multiplique sorrisos.</h2><p>Um brinquedo que já fez parte de uma infância pode iniciar uma nova história. Descubra como participar da nossa iniciativa de doação.</p><a class="btn btn-primary" href="#doacao">Quero fazer uma doação →</a></div><div class="feature-image" style="background-image:url('assets/donation-play.webp')"></div></div></div></section><section class="section-tight"><div class="container"><div class="section-heading"><span class="eyebrow">Quem brinca, conta</span><h2>Histórias que inspiram.</h2><p>Depoimentos ilustrativos para a apresentação acadêmica — não representam avaliações reais de clientes.</p></div><div class="quote-grid"><div class="quote-card"><div class="stars">★★★★★</div><p>“Adorei a proposta de receber brinquedos que fazem sentido para cada fase. A brincadeira ganhou novas possibilidades aqui em casa.”</p><strong>Camila R. · depoimento demonstrativo</strong></div><div class="quote-card"><div class="stars">★★★★★</div><p>“A ideia de compartilhar e dar novos destinos aos brinquedos combina com o que buscamos para nossa família.”</p><strong>Renata M. · depoimento demonstrativo</strong></div><div class="quote-card"><div class="stars">★★★★★</div><p>“A curadoria por idade ajuda a descobrir brincadeiras que eu não teria pensado em apresentar.”</p><strong>João P. · depoimento demonstrativo</strong></div></div></div></section><section class="section"><div class="container"><div class="section-heading"><span class="eyebrow">Conteúdo para famílias</span><h2>Ideias para brincar e crescer junto.</h2><p>Inspiração e informação para tornar a infância ainda mais rica em descobertas.</p></div><div class="article-grid">${articles.map(articleCard).join('')}</div></div></section><section class="section-tight"><div class="container"><div class="feature-band"><div class="feature-copy"><span class="eyebrow">Uma infância com mais possibilidades</span><h2>Vamos criar novas histórias?</h2><p>Descubra brinquedos, conheça o clube e faça parte de uma comunidade que acredita no poder de brincar.</p><a class="btn btn-primary" href="#brinquedos">Explore a Bambin →</a></div><div class="feature-image"></div></div></div></section>`}
function benefitCards(){return [{i:'✦',t:'Desenvolvimento cognitivo',d:'Explorar, comparar, criar hipóteses e descobrir relações.'},{i:'⌁',t:'Coordenação motora',d:'Experimentar movimentos, encaixes e diferentes gestos.'},{i:'✿',t:'Criatividade e imaginação',d:'Inventar histórias, cenários e novas possibilidades.'},{i:'◌',t:'Desenvolvimento sensorial',d:'Perceber texturas, sons, formas e contrastes.'},{i:'♡',t:'Linguagem e comunicação',d:'Compartilhar ideias, narrativas e descobertas.'},{i:'☼',t:'Socioemocional',d:'Expressar emoções e aprender em situações de brincadeira.'},{i:'⌘',t:'Raciocínio lógico',d:'Observar padrões, organizar sequências e resolver desafios.'},{i:'◎',t:'Concentração',d:'Dedicar atenção a uma atividade no próprio ritmo.'},{i:'↗',t:'Autonomia',d:'Fazer escolhas e experimentar caminhos próprios.'},{i:'♧',t:'Socialização',d:'Compartilhar, cooperar e respeitar diferentes turnos.'}].map(x=>`<article class="benefit-card"><div class="benefit-icon">${x.i}</div><h3>${x.t}</h3><p>${x.d}</p></article>`).join('')}
function articleCard(a){return `<article class="article-card"><img src="assets/${a.img}" alt="${a.title}" loading="lazy"><div class="article-body"><span class="eyebrow">Guia Bambin</span><h3>${a.title}</h3><p>${a.desc}</p><button class="text-link" data-article="${a.id}">Leia mais →</button></div></article>`}
function catalog(){let list=products.filter(p=>(activeFilter==='all'||p.group===activeFilter)&&(`${p.name} ${p.age} ${p.short}`).toLowerCase().includes(searchTerm.toLowerCase()));return `<section class="page-hero"><div class="page-heading"><span class="eyebrow">Catálogo Bambin</span><h1>Brincadeiras que acompanham cada descoberta.</h1><p>Escolha brinquedos avulsos, sem precisar contratar uma assinatura. Os valores são demonstrativos e editáveis.</p></div></section><section class="page-content"><div class="container"><div class="filters"><div class="filter-pills">${[['all','Todos'],['0-1','0 a 12 meses'],['1-2','1 a 2 anos'],['3-4','3 a 4 anos'],['5-6','5 a 6 anos'],['7-10','7 a 10 anos']].map(([v,t])=>`<button class="filter-pill ${activeFilter===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div><select class="sort-select" id="sortProducts" aria-label="Ordenar produtos"><option value="default">Ordenar: relevância</option><option value="low">Menor preço</option><option value="high">Maior preço</option></select></div><div class="product-grid" id="catalogGrid">${list.length?list.map(productCard).join(''):'<div class="search-empty">Não encontramos brinquedos com esse termo. Tente outra busca.</div>'}</div></div></section>`}
function productPage(id){const p=productById(id);if(!p)return notFound();return `<section class="page-content"><div class="container"><div class="product-detail-layout"><img src="assets/${p.image}" alt="${p.name}"><div class="detail-copy"><span class="eyebrow">Brinquedo educativo · ${p.age}</span><h1>${p.name}</h1><p>${p.short}</p><div class="price">${money(p.price)} <small>preço demonstrativo</small></div><p style="font-size:11px">Compra avulsa · sem assinatura</p><div class="product-actions"><button class="btn btn-primary" data-add="${p.id}">Adicionar à sacola</button><button class="btn btn-outline" data-fav="${p.id}">${favorites.includes(p.id)?'♥ Favoritado':'♡ Favoritar'}</button></div><div class="notice" style="margin-top:18px">Valores, materiais e especificações são ilustrativos para o projeto acadêmico e deverão ser confirmados antes de uma operação comercial.</div><div class="detail-section"><h3>Descubra tudo o que essa brincadeira proporciona</h3><p>${p.description}</p><p><strong>Como brincar:</strong> ${p.how}</p><p><strong>Materiais:</strong> ${p.materials}</p></div><div class="detail-section"><h3>Habilidades estimuladas</h3><ul>${p.benefits.map(b=>`<li>${b}</li>`).join('')}</ul></div><div class="detail-section"><h3>Cuidados e recomendações</h3><p>${p.safety}</p></div><div class="detail-section"><h3>Por que escolher esse brinquedo?</h3><p>Na fase de ${p.age}, a criança pode se beneficiar de oportunidades para experimentar, repetir e descobrir novas possibilidades. Este brinquedo propõe uma experiência relacionada a essa etapa, sempre respeitando o interesse e o ritmo individual.</p></div></div></div></div></section>`}
function club(){return `<section class="page-hero"><div class="page-heading"><span class="eyebrow">Clube de Assinatura Bambin</span><h1>Uma nova descoberta em cada fase.</h1><p>Escolha a faixa etária e receba uma curadoria demonstrativa de brinquedos educativos para transformar o aprendizado em diversão.</p></div></section><section class="page-content"><div class="container"><div class="section-heading"><h2>Conheça nossos três planos</h2><p>Preços, quantidade e periodicidade são hipóteses comerciais ilustrativas e editáveis para o TCC.</p></div><div class="plan-grid">${plans.map((p,i)=>`<article class="plan-card ${i===1?'featured':''}"><img src="assets/${p.img}" alt="${p.name}" loading="lazy"><span class="age">${p.age}</span><h3>${p.name}</h3><p>${p.desc}</p><ul>${p.benefits.map(b=>`<li>${b}</li>`).join('')}</ul><p><strong>Exemplos:</strong> ${p.examples}</p><p><strong>${p.qty}</strong><br><small>${p.period} (demonstrativo)</small></p><div class="plan-price">${money(p.price)} <small>/ ciclo</small></div><div class="plan-actions"><button class="btn btn-outline btn-small" data-plan="${p.id}">Conhecer plano</button><button class="btn btn-primary btn-small" data-subscribe="${p.id}">Assinar agora</button></div></article>`).join('')}</div><div class="section section-tight"><div class="section-heading"><span class="eyebrow">Compare antes de escolher</span><h2>Planos lado a lado</h2></div><table class="comparison"><thead><tr><th>Benefício</th>${plans.map(p=>`<th>${p.name}</th>`).join('')}</tr></thead><tbody><tr><td>Faixa etária</td>${plans.map(p=>`<td>${p.age}</td>`).join('')}</tr><tr><td>Brinquedos por envio</td>${plans.map(p=>`<td>${p.qty}</td>`).join('')}</tr><tr><td>Periodicidade</td>${plans.map(p=>`<td>${p.period}</td>`).join('')}</tr><tr><td>Valor ilustrativo</td>${plans.map(p=>`<td>${money(p.price)}</td>`).join('')}</tr><tr><td>Curadoria por fase</td>${plans.map(()=>'<td>✓</td>').join('')}</tr></tbody></table></div><div class="section-tight"><div class="section-heading"><h2>Como funciona?</h2><p>Três passos simples para começar uma nova jornada de descobertas.</p></div><div class="steps"><div class="step-card"><span class="step-num">1</span><h3>Escolha seu plano</h3><p>Selecione a faixa etária e informe a idade da criança no fluxo demonstrativo.</p></div><div class="step-card"><span class="step-num">2</span><h3>Receba uma curadoria</h3><p>Uma seleção de brinquedos pensada para a fase e os interesses da criança.</p></div><div class="step-card"><span class="step-num">3</span><h3>Descubra e brinque</h3><p>Aproveite novas experiências e acompanhe as próximas etapas do desenvolvimento.</p></div></div></div></div></section>`}
function planModal(id){const p=plansById(id);return `<div class="modal open" id="planModal"><div class="modal-card"><button class="modal-close" data-close-modal>×</button><img src="assets/${p.img}" alt="${p.name}"><span class="eyebrow">${p.age}</span><h2>${p.name}</h2><p>${p.desc}</p><p><strong>O que pode chegar:</strong> ${p.examples}</p><p><strong>Benefícios:</strong> ${p.benefits.join(' · ')}</p><p><strong>Formato ilustrativo:</strong> ${p.qty}, ${p.period.toLowerCase()}, por ${money(p.price)} por ciclo.</p><div class="notice">Condições comerciais demonstrativas. Política de renovação, frete, cancelamento e disponibilidade precisam ser definidos pela empresa antes do lançamento.</div><div class="form-actions"><button class="btn btn-primary" data-subscribe="${p.id}">Assinar agora →</button></div></div></div>`}
function subscribePage(id){const p=plansById(id);if(!p)return notFound();return `<section class="page-hero"><div class="page-heading"><span class="eyebrow">Clube de assinatura</span><h1>Vamos começar uma nova descoberta?</h1><p>Você escolheu o plano ${p.name}. Preencha os dados demonstrativos para simular a contratação.</p></div></section><section class="page-content"><div class="container checkout-layout"><form class="form-card" id="subscribeForm"><h2 style="font:600 27px var(--serif);color:var(--brown);margin:0 0 5px">Dados da família</h2><p style="font-size:12px;color:var(--muted)">Nenhuma cobrança será realizada.</p><div class="form-grid"><div class="field full"><label>Nome do responsável *</label><input name="name" required placeholder="Nome completo"></div><div class="field"><label>E-mail *</label><input type="email" name="email" required placeholder="voce@email.com"></div><div class="field"><label>Telefone *</label><input name="phone" required placeholder="(00) 00000-0000"></div><div class="field"><label>Nome da criança *</label><input name="child" required placeholder="Nome da criança"></div><div class="field"><label>Idade da criança *</label><select name="age" required><option value="">Selecione</option>${Array.from({length:11},(_,i)=>`<option>${i} ${i===1?'ano':'anos'}</option>`).join('')}</select></div><div class="field full"><label>Observações sobre interesses (opcional)</label><textarea name="notes" placeholder="Conte um pouco sobre as brincadeiras favoritas..."></textarea></div></div><div class="notice" style="margin-top:17px">Plano: ${p.name} · ${p.age} · ${p.qty} · ${p.period} · ${money(p.price)} por ciclo (demonstrativo).</div><div class="form-actions"><button class="btn btn-primary">Confirmar simulação de assinatura →</button></div></form><aside class="checkout-summary"><h3>Seu plano</h3><img src="assets/${p.img}" alt="${p.name}" style="width:100%;height:150px;object-fit:cover;border-radius:12px"><p><strong>${p.name}</strong><br><small>${p.age}</small></p><div class="summary-line"><span>Envio</span><span>${p.qty}</span></div><div class="summary-line"><span>Periodicidade</span><span>${p.period}</span></div><div class="summary-line total"><span>Valor por ciclo</span><span>${money(p.price)}</span></div></aside></div></section>`}
function sustainability(){return `<section class="page-hero"><div class="page-heading"><span class="eyebrow">Nosso compromisso</span><h1>Bambin e o futuro: brincar também é cuidar.</h1><p>Experiências significativas podem caminhar junto com escolhas mais conscientes.</p></div></section><section class="page-content"><div class="container"><div class="two-col"><img src="assets/sustainability-play.webp" alt="Brinquedos educativos de madeira em ambiente acolhedor"><div class="copy-block"><span class="eyebrow">Consumo consciente</span><h2>Menos excesso. Mais histórias para contar.</h2><p>A Bambin acredita que a infância não precisa ser medida pela quantidade de brinquedos. Nosso propósito é valorizar a qualidade das experiências, incentivar o compartilhamento e ampliar o tempo de uso de cada item.</p><ul class="check-list"><li>Curadoria que considera a fase e as possibilidades de brincadeira.</li><li>Valorização de brinquedos duráveis e de materiais adequados.</li><li>Incentivo à reutilização e à doação de itens em boas condições.</li><li>Informação para escolhas responsáveis pelas famílias.</li></ul></div></div><div class="section"><div class="section-heading"><h2>Pequenas escolhas, impacto coletivo.</h2><p>Nosso compromisso se traduz em atitudes práticas e em uma relação mais cuidadosa com os objetos e com as pessoas.</p></div><div class="steps"><div class="step-card"><span class="step-num">01</span><h3>Escolher com intenção</h3><p>Priorizar brinquedos adequados à idade e aos interesses da criança.</p></div><div class="step-card"><span class="step-num">02</span><h3>Compartilhar possibilidades</h3><p>Dar novos destinos a brinquedos completos e em boas condições.</p></div><div class="step-card"><span class="step-num">03</span><h3>Reduzir desperdícios</h3><p>Valorizar o cuidado, a manutenção e a reutilização responsável.</p></div></div></div><div class="notice">Compromissos e práticas institucionais apresentados como proposta de marca para o TCC. Metas, fornecedores, certificações e indicadores ambientais deverão ser comprovados antes de qualquer divulgação comercial.</div></div></section>`}
function donation(){return `<section class="page-content"><div class="container"><div class="donation-banner"><div><span class="eyebrow" style="color:#f2d9bb">Pontos de doação Bambin</span><h2>Um brinquedo pode contar muitas histórias. Ajude-o a começar uma nova.</h2><p>Aquilo que já fez parte da infância de uma criança pode levar alegria, descobertas e aprendizado para outra. Doe, compartilhe e transforme histórias.</p><div class="hero-actions"><a class="btn btn-white" href="#form-doacao">Quero fazer uma doação ↓</a><a class="btn btn-outline" style="color:#fff;border-color:#fff" href="#atendimento">Quero saber mais</a></div></div></div><div class="section"><div class="section-heading"><span class="eyebrow">Como funciona?</span><h2>Quatro passos para compartilhar histórias.</h2><p>Uma iniciativa de incentivo à doação e à reutilização de brinquedos em boas condições.</p></div><div class="steps"><div class="step-card"><span class="step-num">1</span><h3>Separe</h3><p>Escolha brinquedos que não são mais utilizados, mas estão em boas condições.</p></div><div class="step-card"><span class="step-num">2</span><h3>Confira</h3><p>Verifique se estão completos, limpos e adequados para uso.</p></div><div class="step-card"><span class="step-num">3</span><h3>Encontre</h3><p>Consulte os pontos de coleta oficiais assim que forem cadastrados.</p></div><div class="step-card"><span class="step-num">4</span><h3>Doe</h3><p>Entregue sua contribuição e ajude a levar novas experiências a outras crianças.</p></div></div></div><div class="section-tight"><div class="section-heading"><span class="eyebrow">O que pode ser doado?</span><h2>Brinquedos que podem ganhar uma nova história.</h2></div><div class="donation-types">${[['▧','Brinquedos educativos','Peças completas, limpas e em boas condições.'],['▦','Jogos e quebra-cabeças','Jogos de tabuleiro e puzzles com todas as peças.'],['▤','Blocos de construção','Conjuntos completos, sem danos ou pontas.'],['♡','Livros infantis','Livros conservados, sem páginas soltas ou rasgos.']].map(x=>`<article class="donation-type"><div class="symbol">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div><div class="notice" style="margin-top:18px"><strong>Não devem ser doados:</strong> brinquedos quebrados, incompletos, sujos, com peças perigosas ou danos que comprometam a segurança. A triagem final deve ser realizada pela equipe responsável.</div></div><div class="section"><div class="section-heading"><span class="eyebrow">Onde doar?</span><h2>Pontos de coleta</h2><p>Os locais oficiais serão divulgados após validação e cadastro pela Bambin.</p></div><div class="two-col"><div class="copy-block"><h2>Estamos preparando nossa rede de acolhimento.</h2><p>Os pontos abaixo são campos de cadastro demonstrativos. Nenhum endereço ou estabelecimento foi inventado ou apresentado como parceiro real.</p><div class="notice"><strong>Local demonstrativo — endereço a cadastrar</strong><br>Nome do estabelecimento: a definir<br>Endereço e bairro: aguardando parceria<br>Horário: a confirmar<br>Contato: a confirmar</div><div class="map-placeholder"><span class="map-pin">●</span><strong>Mapa de pontos de coleta</strong><small>Área ilustrativa · locais oficiais a cadastrar</small></div><p>Quer indicar um local ou participar como parceiro? Preencha o formulário ao lado.</p></div><div class="form-card" id="form-doacao"><h2 style="font:600 25px var(--serif);color:var(--brown);margin:0 0 5px">Quero ser um ponto de doação</h2><p style="font-size:11px;color:var(--muted)">Cadastro de interesse demonstrativo.</p><form id="donationForm"><div class="form-grid"><div class="field full"><label>Nome completo *</label><input name="name" required></div><div class="field"><label>E-mail *</label><input type="email" name="email" required></div><div class="field"><label>Telefone *</label><input name="phone" required></div><div class="field full"><label>Nome do estabelecimento (se houver)</label><input name="place"></div><div class="field"><label>Endereço *</label><input name="address" required></div><div class="field"><label>Bairro *</label><input name="neighborhood" required></div><div class="field full"><label>Mensagem</label><textarea name="message" placeholder="Conte como gostaria de participar..."></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Quero ser um ponto de doação →</button></div></form></div></div></div><div class="section-tight"><div class="feature-band"><div class="feature-copy"><span class="eyebrow">Compartilhe histórias</span><h2>Pequenas atitudes podem criar grandes histórias.</h2><p>Na Bambin, acreditamos que a infância merece ser vivida com oportunidades, descobertas e afeto. Quando compartilhamos brinquedos, compartilhamos também possibilidades de brincar, aprender e criar memórias.</p><a class="btn btn-primary" href="#inicio">Conheça a Bambin →</a></div><div class="feature-image" style="background-image:url('assets/donation-play.webp')"></div></div></div></div></section>`}
function guides(){return `<section class="page-hero"><div class="page-heading"><span class="eyebrow">Guias e conteúdos</span><h1>Ideias para brincar, aprender e crescer junto.</h1><p>Conteúdos para apoiar famílias na escolha de brinquedos e na construção de experiências significativas.</p></div></section><section class="page-content"><div class="container"><div class="article-grid">${articles.map(articleCard).join('')}</div><div class="section-tight"><div class="notice">Conteúdo educativo e informativo. As orientações não substituem a supervisão dos responsáveis nem as instruções de segurança dos fabricantes.</div></div></div></section>`}
function articlePage(id){const a=articles.find(x=>x.id===id);if(!a)return notFound();return `<section class="page-content"><div class="container" style="max-width:850px"><img src="assets/${a.img}" alt="${a.title}" style="width:100%;height:360px;object-fit:cover;border-radius:20px"><div class="copy-block" style="padding:25px 0"><span class="eyebrow">Guia Bambin · leitura demonstrativa</span><h1 style="font:600 42px/1.15 var(--serif);color:var(--brown)">${a.title}</h1><p>${a.body}</p><p>Na Bambin, acreditamos que cada criança tem seu próprio ritmo. A presença de um adulto, a liberdade para experimentar e a escolha consciente de materiais adequados ajudam a tornar a brincadeira mais significativa.</p><a class="text-link" href="#guias">← Voltar aos conteúdos</a></div></div></section>`}
function support(){const qs=[['Como faço uma compra avulsa?','Escolha um brinquedo no catálogo, adicione à sacola e siga para o checkout demonstrativo. Nenhuma cobrança ou pedido real será criado.'],['Como funciona o clube de assinatura?','Escolha um plano por faixa etária e preencha os dados demonstrativos. Preços, quantidades e periodicidade ainda precisam ser definidos pela empresa.'],['Quais são os prazos de entrega?','Os prazos ainda não foram configurados. O site apresenta frete e condições apenas para simulação acadêmica.'],['Como funcionam trocas e devoluções?','A política definitiva deverá ser elaborada conforme a legislação aplicável e as condições comerciais da empresa antes do lançamento.'],['Como posso doar brinquedos?','Consulte os pontos oficiais quando forem cadastrados ou demonstre interesse pelo formulário da página Pontos de Doação.'],['Os brinquedos são certificados?','As certificações e especificações devem ser confirmadas com cada fornecedor. Não há certificação real declarada neste protótipo funcional.']];return `<section class="page-hero"><div class="page-heading"><span class="eyebrow">Estamos aqui para ajudar</span><h1>Atendimento com carinho e clareza.</h1><p>Encontre respostas para suas dúvidas ou envie uma mensagem para a equipe Bambin.</p></div></section><section class="page-content"><div class="container"><div class="section-heading"><h2>Perguntas frequentes</h2></div><div class="faq-list">${qs.map((q,i)=>`<div class="faq-item"><button class="faq-question" data-faq="${i}">${q[0]} <span>＋</span></button><div class="faq-answer">${q[1]}</div></div>`).join('')}</div><div class="section"><div class="two-col"><div class="copy-block"><span class="eyebrow">Fale com a gente</span><h2>Tem outra dúvida? Vamos conversar.</h2><p>Preencha o formulário e nossa equipe poderá retornar quando o canal de atendimento estiver conectado. O envio nesta versão é demonstrativo.</p><p><strong>E-mail:</strong> oi@bambin.com.br<br><strong>Telefone:</strong> (21) 0000-0000<br><strong>Horário:</strong> segunda a sexta, 9h às 18h (demonstrativo)</p><button class="btn btn-brown" data-whatsapp>Conversar pelo WhatsApp ↗</button><p style="font-size:10px">Botão ilustrativo: não há número de WhatsApp conectado.</p></div><form class="form-card" id="contactForm"><div class="form-grid"><div class="field full"><label>Nome completo *</label><input name="name" required></div><div class="field"><label>E-mail *</label><input type="email" name="email" required></div><div class="field"><label>Telefone</label><input name="phone"></div><div class="field full"><label>Assunto *</label><select name="subject" required><option value="">Selecione</option><option>Compra</option><option>Assinatura</option><option>Entrega</option><option>Doação</option><option>Outro assunto</option></select></div><div class="field full"><label>Mensagem *</label><textarea name="message" required></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Enviar mensagem →</button></div></form></div></div></div></section>`}
function favoritesPage(){const list=products.filter(p=>favorites.includes(p.id));return `<section class="page-hero"><div class="page-heading"><span class="eyebrow">Sua lista especial</span><h1>Brinquedos favoritos.</h1><p>Guarde por aqui as brincadeiras que chamaram sua atenção.</p></div></section><section class="page-content"><div class="container"><div class="product-grid">${list.length?list.map(productCard).join(''):'<div class="search-empty">Sua lista ainda está vazia. Explore o catálogo e toque no coração para salvar seus favoritos.</div>'}</div></div></section>`}
function notFound(){return `<section class="page-content"><div class="container empty-state"><div class="empty-icon">✿</div><h3>Essa página ainda não foi encontrada.</h3><a class="btn btn-primary" href="#inicio">Voltar ao início</a></div></section>`}
function checkout(){if(!cart.length)return `<section class="page-content"><div class="container empty-state"><div class="empty-icon">♡</div><h3>Sua sacola está esperando por uma descoberta.</h3><a class="btn btn-primary" href="#brinquedos">Explorar brinquedos</a></div></section>`;return `<section class="page-hero"><div class="page-heading"><span class="eyebrow">Finalização demonstrativa</span><h1>Quase lá. Vamos preparar sua descoberta?</h1><p>Preencha os dados para simular as etapas de compra. Nenhum pagamento será processado.</p></div></section><section class="page-content"><div class="container checkout-layout"><div class="checkout-panel" id="checkoutPanel"></div><aside class="checkout-summary" id="checkoutSummary"></aside></div></section>`}
function renderCheckoutStep(){const panel=document.getElementById('checkoutPanel'),summary=document.getElementById('checkoutSummary');if(!panel)return;const steps=['Responsável','Endereço','Resumo','Pagamento','Confirmação'];const total=cart.reduce((s,i)=>s+i.price*i.qty,0),shipping=total>=180?0:14.90;summary.innerHTML=`<h3>Resumo do pedido</h3>${cart.map(i=>`<div class="summary-product"><img src="assets/${i.image}" alt=""><div><strong>${i.name}</strong><small>Qtd. ${i.qty} · ${money(i.price)}</small></div></div>`).join('')}<div class="summary-line"><span>Subtotal</span><span>${money(total)}</span></div><div class="summary-line"><span>Frete demonstrativo</span><span>${shipping?money(shipping):'Grátis'}</span></div><div class="summary-line total"><span>Total</span><span>${money(total+shipping)}</span></div><div class="notice">Valores de frete e produtos ilustrativos.</div>`;
 if(checkoutStep===5){panel.innerHTML=`<div class="success-state"><div class="success-icon">✓</div><span class="eyebrow">Simulação concluída</span><h2>Obrigado por escolher a Bambin!</h2><p>Estamos muito felizes em fazer parte das descobertas e histórias da sua família.</p><p style="font-size:11px">Pedido demonstrativo nº BB-${Math.floor(10000+Math.random()*89999)}. Nenhum pagamento foi realizado ou dado bancário armazenado.</p><button class="btn btn-primary" id="finishCheckout">Voltar à loja →</button></div>`;return}
 panel.innerHTML=`<div class="progress">${steps.slice(0,4).map((s,i)=>`<span class="${i<checkoutStep?'done':''}"></span>`).join('')}</div><span class="eyebrow">Etapa ${checkoutStep} de 4 · ${steps[checkoutStep-1]}</span>${checkoutStep===1?`<h2>Dados do responsável</h2><form id="checkoutForm"><div class="form-grid"><div class="field full"><label>Nome completo *</label><input name="name" required value="${checkoutData.name||''}"></div><div class="field"><label>E-mail *</label><input type="email" name="email" required value="${checkoutData.email||''}"></div><div class="field"><label>Telefone *</label><input name="phone" required value="${checkoutData.phone||''}"></div><div class="field full"><label>CPF (opcional nesta simulação)</label><input name="cpf" placeholder="000.000.000-00" value="${checkoutData.cpf||''}"></div></div><div class="step-controls"><span></span><button class="btn btn-primary">Continuar →</button></div></form>`:checkoutStep===2?`<h2>Endereço de entrega</h2><form id="checkoutForm"><div class="form-grid"><div class="field"><label>CEP *</label><input name="cep" required value="${checkoutData.cep||''}" placeholder="00000-000"></div><div class="field"><label>Número *</label><input name="number" required value="${checkoutData.number||''}"></div><div class="field full"><label>Rua *</label><input name="street" required value="${checkoutData.street||''}"></div><div class="field"><label>Complemento</label><input name="complement" value="${checkoutData.complement||''}"></div><div class="field"><label>Bairro *</label><input name="district" required value="${checkoutData.district||''}"></div><div class="field"><label>Cidade *</label><input name="city" required value="${checkoutData.city||''}"></div><div class="field"><label>Estado *</label><select name="state" required><option value="">Selecione</option>${['RJ','SP','MG','ES','PR','SC','RS','DF','BA','PE','CE','GO','MT','MS','PA','AM','PB','RN','AL','SE','PI','MA','TO','RO','AC','AP','RR'].map(s=>`<option ${checkoutData.state===s?'selected':''}>${s}</option>`).join('')}</select></div></div><div class="step-controls"><button type="button" class="btn btn-outline" data-back-step>← Voltar</button><button class="btn btn-primary">Continuar →</button></div></form>`:checkoutStep===3?`<h2>Revise seu pedido</h2>${cart.map(i=>`<div class="summary-product"><img src="assets/${i.image}" alt=""><div><strong>${i.name}</strong><small>${i.qty} × ${money(i.price)} = ${money(i.qty*i.price)}</small></div></div>`).join('')}<div class="step-controls"><button type="button" class="btn btn-outline" data-back-step>← Voltar</button><button class="btn btn-primary" data-next-step>Confirmar resumo →</button></div>`:`<h2>Forma de pagamento</h2><p>Escolha uma opção apenas para concluir a demonstração.</p><form id="checkoutForm"><div class="field"><label><input type="radio" name="payment" value="Cartão de crédito" required> Cartão de crédito (simulação)</label><label><input type="radio" name="payment" value="PIX"> PIX (simulação)</label></div><div class="notice" style="margin-top:18px">Não informe número de cartão, código de segurança, senha ou dados bancários. Nenhuma transação será realizada.</div><div class="step-controls"><button type="button" class="btn btn-outline" data-back-step>← Voltar</button><button class="btn btn-primary">Finalizar simulação →</button></div></form>`}`;
}
function render(){const [route,arg]=location.hash.replace(/^#/,'').split('/');document.querySelectorAll('.main-nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`#${route||'inicio'}`));switch(route||'inicio'){case'inicio':app.innerHTML=home();break;case'brinquedos':app.innerHTML=catalog();break;case'produto':app.innerHTML=productPage(arg);break;case'clube':app.innerHTML=club();break;case'assinar':app.innerHTML=subscribePage(arg);break;case'sustentabilidade':app.innerHTML=sustainability();break;case'doacao':app.innerHTML=donation();break;case'guias':app.innerHTML=guides();break;case'artigo':app.innerHTML=articlePage(arg);break;case'atendimento':app.innerHTML=support();break;case'favoritos':app.innerHTML=favoritesPage();break;case'checkout':app.innerHTML=checkout();renderCheckoutStep();break;default:app.innerHTML=notFound()}window.scrollTo({top:0,behavior:'smooth'});document.getElementById('mainNav').classList.remove('open');document.getElementById('mobileMenu').setAttribute('aria-expanded','false')}
function addToCart(id){const p=productById(id);if(!p)return;const found=cart.find(i=>i.id===id);if(found)found.qty++;else cart.push({id:p.id,name:p.name,price:p.price,image:p.image,qty:1,type:'product'});persist();renderDrawer();toast(`${p.name} foi adicionada à sacola.`)}
function toggleFavorite(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];persist();if(location.hash==='#favoritos')render();else{document.querySelectorAll(`[data-fav="${id}"]`).forEach(b=>{b.classList.toggle('active',favorites.includes(id));b.textContent=favorites.includes(id)?'♥':'♡'});toast(favorites.includes(id)?'Adicionado aos favoritos.':'Removido dos favoritos.')}}
function renderDrawer(){const drawer=document.getElementById('cartDrawer'),items=document.getElementById('drawerItems'),summary=document.getElementById('drawerSummary');if(!cart.length){items.innerHTML='<div class="empty-state"><div class="empty-icon">♡</div><h3>Sua sacola está vazia</h3><p>Escolha uma brincadeira para começar.</p><a class="btn btn-primary" href="#brinquedos">Explorar brinquedos</a></div>';summary.innerHTML='';return}items.innerHTML=cart.map(i=>`<div class="cart-line"><img src="assets/${i.image}" alt=""><div><strong>${i.name}</strong><small>${money(i.price)} · ${i.type==='subscription'?'assinatura demonstrativa':'compra avulsa'}</small><div class="qty-control"><button data-qty="${i.id}" data-delta="-1">−</button><span>${i.qty}</span><button data-qty="${i.id}" data-delta="1">+</button></div></div><button class="remove-line" data-remove="${i.id}" aria-label="Remover">×</button></div>`).join('');const total=cart.reduce((s,i)=>s+i.price*i.qty,0);summary.innerHTML=`<div class="summary-line"><span>Subtotal</span><strong>${money(total)}</strong></div><div class="summary-line"><span>Frete</span><span>Calculado na simulação</span></div><button class="btn btn-primary" style="width:100%;margin-top:12px" id="goCheckout">Ir para finalização →</button><p style="font-size:9px;color:var(--muted);text-align:center">Checkout demonstrativo. Nenhuma cobrança será realizada.</p>`}
function openCart(){renderDrawer();document.getElementById('overlay').classList.add('open');document.getElementById('cartDrawer').classList.add('open');document.getElementById('cartDrawer').setAttribute('aria-hidden','false')}
function closeCart(){document.getElementById('overlay').classList.remove('open');document.getElementById('cartDrawer').classList.remove('open');document.getElementById('cartDrawer').setAttribute('aria-hidden','true')}
function closeModal(){document.querySelectorAll('.modal').forEach(m=>m.remove())}
function submitDemo(form,msg){if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form).entries());console.info('Bambin — envio demonstrativo:',data);form.reset();toast(msg)}
// Global interactions are delegated so dynamically rendered cards remain functional.
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.id==='cartButton'){openCart();return}if(t.id==='closeCart'||t.id==='overlay'){closeCart();return}if(t.id==='favoritesButton'){go('favoritos');return}if(t.id==='mobileMenu'){const nav=document.getElementById('mainNav');nav.classList.toggle('open');t.setAttribute('aria-expanded',nav.classList.contains('open'));return}if(t.dataset.add){addToCart(t.dataset.add);return}if(t.dataset.fav){toggleFavorite(t.dataset.fav);return}if(t.dataset.product){go(`produto/${t.dataset.product}`);return}if(t.dataset.filter){activeFilter=t.dataset.filter;searchTerm='';if(location.hash!=='#brinquedos')go('brinquedos');else render();return}if(t.dataset.plan){const p=plansById(t.dataset.plan);closeModal();document.body.insertAdjacentHTML('beforeend',planModal(p.id));return}if(t.dataset.subscribe){closeModal();go(`assinar/${t.dataset.subscribe}`);return}if(t.dataset.article){go(`artigo/${t.dataset.article}`);return}if(t.dataset.closeModal){closeModal();return}if(t.dataset.qty){const item=cart.find(i=>i.id===t.dataset.qty);if(item){item.qty+=Number(t.dataset.delta);if(item.qty<1)cart=cart.filter(i=>i.id!==item.id);persist();renderDrawer()}return}if(t.dataset.remove){cart=cart.filter(i=>i.id!==t.dataset.remove);persist();renderDrawer();toast('Item removido da sacola.');return}if(t.id==='goCheckout'){closeCart();checkoutStep=1;checkoutData={};go('checkout');return}if(t.dataset.faq){const item=t.closest('.faq-item');item.classList.toggle('open');t.querySelector('span').textContent=item.classList.contains('open')?'−':'＋';return}if(t.hasAttribute('data-back-step')){checkoutStep=Math.max(1,checkoutStep-1);renderCheckoutStep();return}if(t.hasAttribute('data-next-step')){checkoutStep=4;renderCheckoutStep();return}if(t.id==='finishCheckout'){cart=[];persist();checkoutStep=1;checkoutData={};go('inicio');toast('Até a próxima descoberta!');return}if(t.hasAttribute('data-whatsapp')){toast('WhatsApp demonstrativo: conecte um número oficial para ativar este canal.');return}});
document.addEventListener('submit',e=>{if(e.target.id==='donationForm'){e.preventDefault();submitDemo(e.target,'Interesse registrado nesta demonstração.');return}if(e.target.id==='contactForm'){e.preventDefault();submitDemo(e.target,'Mensagem simulada com sucesso.');return}if(e.target.id==='subscribeForm'){e.preventDefault();if(!e.target.reportValidity())return;const data=Object.fromEntries(new FormData(e.target).entries());console.info('Bambin — assinatura demonstrativa:',data);app.innerHTML=`<section class="page-content"><div class="container"><div class="success-state"><div class="success-icon">✓</div><span class="eyebrow">Solicitação demonstrativa</span><h2>Que bom ter vocês com a gente!</h2><p>O interesse no plano foi registrado apenas nesta demonstração. Nenhuma cobrança ou assinatura real foi criada.</p><a class="btn btn-primary" href="#clube">Voltar aos planos</a></div></div></section>`;return}if(e.target.id==='checkoutForm'){e.preventDefault();if(!e.target.reportValidity())return;const data=Object.fromEntries(new FormData(e.target).entries());checkoutData={...checkoutData,...data};if(checkoutStep===1)checkoutStep=2;else if(checkoutStep===2)checkoutStep=3;else if(checkoutStep===4)checkoutStep=5;renderCheckoutStep();return}});
document.getElementById('searchInput').addEventListener('input',e=>{searchTerm=e.target.value;if(location.hash!=='#brinquedos')go('brinquedos');else{const grid=document.getElementById('catalogGrid');if(grid){const list=products.filter(p=>(activeFilter==='all'||p.group===activeFilter)&&(`${p.name} ${p.age} ${p.short}`).toLowerCase().includes(searchTerm.toLowerCase()));grid.innerHTML=list.length?list.map(productCard).join(''):'<div class="search-empty">Não encontramos brinquedos com esse termo.</div>'}}});
document.addEventListener('change',e=>{if(e.target.id==='sortProducts'){const order=e.target.value;const list=[...products].filter(p=>(activeFilter==='all'||p.group===activeFilter)&&(`${p.name} ${p.age} ${p.short}`).toLowerCase().includes(searchTerm.toLowerCase()));if(order==='low')list.sort((a,b)=>a.price-b.price);if(order==='high')list.sort((a,b)=>b.price-a.price);document.getElementById('catalogGrid').innerHTML=list.map(productCard).join('')}});
window.addEventListener('hashchange',()=>{render();});
updateCounts();render();
